271	    /**
272	     * Return the Pet with the given name, or null if none found for this Owner.
273	     *
274	     * @param name to test
275	     * @return true if pet name is already in use
276	     */
277	    public Pet getPet(String name) {
278	        return getPet(name, false);
279	    }
280	
281	    /**
282	     * Return the Pet with the given name, or null if none found for this Owner.
283	     *
284	     * @param name to test
285	     * @return true if pet name is already in use
286	     */
287	    public Pet getPet(String name, boolean ignoreNew) {
288	        name = name.toLowerCase();
289	        for (Pet pet : getPetsInternal()) {
290	            if (!ignoreNew || !pet.isNew()) {
291	                String compName = pet.getName();
292	                compName = compName.toLowerCase();
293	                if (compName.equals(name)) {
294	                    return pet;
295	                }
296	            }
297	        }
298	        return null;
299	    }
300	
301	    public Pet getPet(Integer petId) {
302	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
303	    }
304	
305	    @Override
306	    public String toString() {
307	        return new ToStringCreator(this)
308	
309	            .append("id", this.getId())
310	            .append("new", this.isNew())
311	            .append("lastName", this.getLastName())
312	            .append("firstName", this.getFirstName())
313	            .append("address", this.address)
314	            .append("city", this.city)
315	            .append("telephone", this.telephone)
316	            .append("email", this.email)
317	            .toString();
318	    }
319	}
