17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.LinkedHashMap;
20	import java.util.Map;
21	import java.util.concurrent.atomic.AtomicLong;
22	
23	import org.slf4j.Logger;
24	import org.slf4j.LoggerFactory;
25	import org.springframework.samples.petclinic.model.Owner;
26	import org.springframework.stereotype.Component;
27	
28	import tools.jackson.databind.ObjectMapper;
29	import tools.jackson.databind.json.JsonMapper;
30	
31	/**
32	 * Owns the owner-create audit concern: the single place that records the audit trail for a
33	 * successfully created {@link Owner}.
34	 *
35	 * <p>Keeping the audit trail here means every create side-effect that must be observable to an
36	 * auditor is emitted from one place, in one form, on the dedicated {@code AUDIT} logger — so the
37	 * registrar is left holding only the create pipeline, and what is audited on create can evolve
38	 * without threading logging detail back through it.
39	 */
40	@Component
41	public class OwnerAuditor {
42	
43	    /** Dedicated audit logger; emits the audit trail on successful owner create. */
44	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
45	
46	    /** Serializes the structured owner-created event to a compact JSON object. */
47	    private static final ObjectMapper MAPPER = JsonMapper.builder().build();
48	
49	    /**
50	     * Monotonically increasing sequence stamped onto each structured owner-created event. The
51	     * auditor is a singleton, so this counter runs across every create for the life of the
52	     * application, giving the emitted events a strict, gap-free order.
53	     */
54	    private final AtomicLong sequence = new AtomicLong();
55	
56	    /**
57	     * Record the audit trail for an owner that has just been created: emit the audit line naming
58	     * the owner's id, member id, registration date and membership level, followed by the immutable
59	     * structured event carrying the same create. Called once, after the owner is persisted, with
60	     * the owner in its final stored form.
61	     *
62	     * @param owner           the freshly persisted owner
63	     * @param membershipLevel the owner's derived membership level, as computed for this create
64	     */
65	    public void ownerCreated(Owner owner, int membershipLevel) {
66	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
67	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
68	        AUDIT.info(structuredEvent(owner, membershipLevel));
69	    }
70	
71	    /**
72	     * Build the immutable structured owner-created event as a JSON object
73	     * {@code {schemaVersion:2, seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}.
74	     * {@code schemaVersion} is the version-2 audit schema tag; {@code seq} is the next value of the
75	     * monotonic {@link #sequence}, so every event carries a distinct, ordered sequence number across
76	     * creates.
77	     *
78	     * <p>{@code memberId} carries the owner's primary identifier — the version-2 member id — read
79	     * from {@link #primaryIdentifier} rather than being spelled out here.
80	     */
81	    private String structuredEvent(Owner owner, int membershipLevel) {
82	        Map<String, Object> event = new LinkedHashMap<>();
83	        event.put("schemaVersion", 2);
84	        event.put("seq", sequence.incrementAndGet());
85	        event.put("ownerId", owner.getId());
86	        event.put("memberId", primaryIdentifier(owner));
87	        event.put("membershipLevel", membershipLevel);
88	        event.put("event", "OWNER_CREATED");
89	        return MAPPER.writeValueAsString(event);
90	    }
91	
92	    /**
93	     * The owner's primary identifier as it stands at this create: the unified member id. This is
94	     * the single point that decides which field is primary, so every emitted event carries the
95	     * member id.
96	     */
97	    private String primaryIdentifier(Owner owner) {
98	        return owner.getMemberId();
99	    }
100	}
