17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import org.springframework.http.HttpStatus;
20	
21	/**
22	 * Signals that a create rule refused to register an owner. This is the one way the create
23	 * pipeline reports a rejection: rather than constructing an HTTP response inline, each rule
24	 * names its refusal as a {@link Reason} and throws, and {@link ExceptionControllerAdvice#handleOwnerRegistrationException}
25	 * turns it into the response the endpoint returns.
26	 *
27	 * <p>The catalogue of refusals lives on {@link Reason}, which pairs every business cause with
28	 * the HTTP status it reports, so the mapping is defined in one place instead of being spread
29	 * across the rejection sites.
30	 */
31	public class OwnerRegistrationException extends RuntimeException {
32	
33	    /**
34	     * The business reasons a create can be refused, each paired with the HTTP status the
35	     * endpoint reports for it. Adding a rejection to the pipeline means adding a constant here,
36	     * so every refusal is named and its status is defined in a single place.
37	     */
38	    public enum Reason {
39	
40	        /** A supplied registration date is later than the server's current date. */
41	        REGISTRATION_DATE_IN_FUTURE(HttpStatus.BAD_REQUEST, "The supplied registration date is in the future"),
42	
43	        /** The per-day create quota for the registration date has already been reached. */
44	        DAILY_CREATE_LIMIT_REACHED(HttpStatus.TOO_MANY_REQUESTS, "The daily create limit for this registration date has been reached"),
45	
46	        /** The owner supplies no usable address in either the structured or the flat form. */
47	        ADDRESS_MISSING(HttpStatus.BAD_REQUEST, "The owner has no usable address"),
48	
49	        /** The telephone cannot be normalized or has an invalid national number length. */
50	        TELEPHONE_INVALID(HttpStatus.BAD_REQUEST, "The supplied telephone number is invalid"),
51	
52	        /** A supplied email is not a syntactically valid address. */
53	        EMAIL_INVALID(HttpStatus.BAD_REQUEST, "The supplied email address is not valid"),
54	
55	        /** A supplied email belongs to a disposable-address domain. */
56	        EMAIL_DISPOSABLE(HttpStatus.BAD_REQUEST, "The supplied email address belongs to a disposable-address domain"),
57	
58	        /** A supplied postcode is malformed or out of range for the owner's city. */
59	        POSTCODE_INVALID(HttpStatus.BAD_REQUEST, "The supplied postcode is malformed or out of range for the owner's city"),
