164	    public static int luhn(String s) {
165	        int sum = 0;
166	        boolean doubling = true;
167	        for (int i = s.length() - 1; i >= 0; i--) {
168	            char c = s.charAt(i);
169	            if (c < '0' || c > '9') {
170	                continue;
171	            }
172	            int d = c - '0';
173	            if (doubling) {
174	                d *= 2;
175	                if (d > 9) {
176	                    d -= 9;
177	                }
178	            }
179	            sum += d;
180	            doubling = !doubling;
181	        }
182	        return (10 - (sum % 10)) % 10;
