324	    private int cappedByHousehold(Owner owner, int level) {
325	        Integer id = owner.getId();
326	        String householdId = owner.getHouseholdId();
327	        if (id == null || householdId == null) {
328	            return level;
329	        }
330	        OptionalInt maxExisting = clinicService.findAllOwners().stream()
331	            .filter(existing -> !existing.isDeleted())
332	            .filter(existing -> existing.getId() != null && existing.getId() < id)
333	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
334	            .mapToInt(this::membershipLevel)
