18	
19	import java.util.Map;
20	
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Resolves an owner's city to its canonical region using a single fixed table.
25	 *
26	 * <p>Keeping this in one place means every rule that is keyed by an owner's region reads
27	 * the same city-to-region mapping, so they can never drift apart: the region a city
28	 * derives here is the region every region-keyed rule sees for that city.
29	 *
30	 * <p>A city not listed in the table has no known region and resolves to
31	 * {@link #UNKNOWN_REGION}.
32	 */
33	@Component
34	public class CityRegionResolver {
35	
36	    /** The region returned for a city that is not in the fixed {@link #CITY_REGION} table. */
37	    public static final String UNKNOWN_REGION = "UNKNOWN";
38	
39	    /** The fixed version-2 tag mixed into the region code used inside an owner's identifiers, so the
40	     *  identity region can never coincide with a plain region and every version-2 identifier differs
41	     *  from its version-1 counterpart. It is stamped only inside identifiers, never in the
42	     *  user-facing locality, timezone or owner-segment region. */
43	    public static final String IDENTITY_VERSION_TAG = "V2";
44	
45	    /** Fixed city-to-region table; a city not listed here has no known region. */
46	    private static final Map<String, String> CITY_REGION = Map.of(
47	        "Sydney", "NSW",
48	        "Melbourne", "VIC",
49	        "Brisbane", "QLD");
50	
51	    /** Fixed region-to-postcode range table (inclusive 4-digit low/high), keyed by region; a
52	     *  region not listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode. */
53	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
54	        "NSW", new int[] {2000, 2099},
55	        "VIC", new int[] {3000, 3099},
56	        "QLD", new int[] {4000, 4099});
57	
58	    /** Fixed region-to-timezone table (IANA names), keyed by region; a region not listed here
59	     *  has no known timezone. */
60	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
61	        "NSW", "Australia/Sydney",
62	        "VIC", "Australia/Melbourne",
63	        "QLD", "Australia/Brisbane");
64	
65	    /**
66	     * Resolve a city to its canonical region.
67	     *
68	     * @param city the owner's city, as stored
69	     * @return the region the city belongs to, or {@link #UNKNOWN_REGION} when the city is
70	     *         not in the fixed table
71	     */
72	    public String regionFor(String city) {
73	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
74	    }
75	
76	    /**
77	     * Resolve a region preferring the postcode over the city. The {@code postcode} is looked up
78	     * against the region postcode ranges first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only
79	     * when the postcode is absent, non-numeric or in no known range does this fall back to the
80	     * city-to-region table. For a known city with a matching postcode both agree; a postcode in a
81	     * different region's range disambiguates cities that share a name.
82	     *
83	     * @param city     the owner's city, as stored
84	     * @param postcode a 4-digit postcode string (e.g. '3000'), or {@code null} when absent
85	     * @return the region derived from the postcode, else the region derived from the city, else
86	     *         {@link #UNKNOWN_REGION}
87	     */
88	    public String regionFor(String city, String postcode) {
89	        String region = regionForPostcode(postcode);
90	        return region != null ? region : regionFor(city);
91	    }
92	
93	    /**
94	     * The region code stamped INSIDE an owner's derived identifiers (the REGION segment of its
95	     * memberId, and the region any other identity code mixes in), resolved preferring the postcode
96	     * over the city exactly as {@link #regionFor(String, String)}.
97	     *
98	     * <p>This is a deliberately separate seam from the user-facing locality region. Under the
99	     * version-2 identity it is the plain region with the fixed {@link #IDENTITY_VERSION_TAG version
100	     * tag} mixed in (e.g. 'V2NSW'), so every identifier that embeds it differs from its version-1
101	     * counterpart and no version-1 identifier is ever produced again. The tag lives only inside
102	     * identifiers; the plain region reported as an owner's locality, timezone or segment area is
103	     * left untouched.
104	     *
105	     * @param city     the owner's city, as stored
106	     * @param postcode a 4-digit postcode string (e.g. '2000'), or {@code null} when absent
107	     * @return the version-2 region code to embed in the owner's identifiers
108	     */
109	    public String identityRegionFor(String city, String postcode) {
110	        return IDENTITY_VERSION_TAG + regionFor(city, postcode);
111	    }
112	
113	    /**
114	     * The plain region underlying a version-2 identity region, i.e. the value returned by
115	     * {@link #identityRegionFor} with the fixed {@link #IDENTITY_VERSION_TAG version tag} stripped
116	     * back off (e.g. 'V2NSW' -> 'NSW'). This recovers the tag-free region that user-facing
117	     * derivations (such as the owner segment) key on without leaking the version tag.
118	     *
119	     * @param identityRegion an identity region as returned by {@link #identityRegionFor}
120	     * @return the identity region with the version tag removed
121	     */
122	    public String plainRegionOfIdentity(String identityRegion) {
123	        if (identityRegion != null && identityRegion.startsWith(IDENTITY_VERSION_TAG)) {
124	            return identityRegion.substring(IDENTITY_VERSION_TAG.length());
125	        }
126	        return identityRegion;
127	    }
128	
129	    /**
130	     * The IANA timezone name for a region, using the fixed region-to-timezone table
131	     * (NSW -> Australia/Sydney, VIC -> Australia/Melbourne, QLD -> Australia/Brisbane).
132	     *
133	     * @param region the canonical region code (e.g. 'NSW'), such as returned by {@link #regionFor}
134	     * @return the region's IANA timezone name, or {@code null} when the region is not in the table
135	     */
136	    public String timezoneForRegion(String region) {
137	        return REGION_TIMEZONE.get(region);
138	    }
139	
140	    /**
141	     * The region whose postcode range contains {@code postcode}, or {@code null} when the postcode
142	     * is absent, non-numeric or in no known range.
143	     */
144	    private String regionForPostcode(String postcode) {
145	        if (postcode == null || postcode.isBlank()) {
146	            return null;
147	        }
148	        int value;
149	        try {
150	            value = Integer.parseInt(postcode.trim());
151	        }
152	        catch (NumberFormatException ex) {
153	            return null;
154	        }
155	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
156	            int[] range = entry.getValue();
157	            if (value >= range[0] && value <= range[1]) {
158	                return entry.getKey();
159	            }
160	        }
161	        return null;
162	    }
163	
164	    /**
165	     * Whether a 4-digit {@code postcode} is valid for the given {@code city}. The postcode is
166	     * checked against the inclusive range of the city's region (NSW 2000-2099, VIC 3000-3099,
167	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode.
168	     *
169	     * @param city     the owner's city, as stored
170	     * @param postcode a 4-digit postcode string (e.g. '2000')
171	     * @return {@code true} if the postcode is within the city's region range, or the city has
172	     *         no known region; {@code false} if the postcode is out of range for the region
173	     */
174	    public boolean isPostcodeValidForCity(String city, String postcode) {
175	        int[] range = REGION_POSTCODE_RANGE.get(regionFor(city));
176	        if (range == null) {
177	            return true;
178	        }
179	        int value = Integer.parseInt(postcode);
180	        return value >= range[0] && value <= range[1];
181	    }
182	}
