17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.Locale;
20	import java.util.Set;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Classifies an owner's email by its domain against the fixed table of known disposable
26	 * domains.
27	 *
28	 * <p>Keeping this in one place means every rule keyed on an owner's email domain reads the
29	 * same disposable-domain table and derives the domain the one way, so they can never drift
30	 * apart: the domain an email yields here is the domain every domain-keyed rule sees for it.
31	 */
32	@Component
33	public class EmailDomainClassifier {
34	
35	    /** Fixed table of disposable email domains; an email whose domain matches one of these
36	     *  (case-insensitively) is a disposable-domain email. */
37	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
38	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
39	
40	    /**
41	     * The lower-cased domain of an email address: the part after its single '@'. Returns
42	     * {@code null} when {@code email} is {@code null} or carries no '@'.
43	     *
44	     * @param email an email address, expected to carry a single '@' (as produced by the
45	     *              create endpoint's syntactic email check)
46	     * @return the lower-cased domain, or {@code null} when the email has none
47	     */
48	    public String domainOf(String email) {
49	        if (email == null) {
50	            return null;
51	        }
52	        int at = email.indexOf('@');
53	        if (at < 0) {
54	            return null;
55	        }
56	        return email.substring(at + 1).toLowerCase(Locale.ROOT);
57	    }
58	
59	    /**
60	     * Whether an email's {@link #domainOf domain} is one of the known disposable domains
61	     * (compared case-insensitively). This is the single disposable-domain check on create,
62	     * so a disposable email is recognised the one way wherever the rule is applied.
63	     *
64	     * @param email an email address, expected to carry a single '@'
65	     * @return {@code true} if the email's domain is a known disposable domain, {@code false}
66	     *         otherwise (including when the email has no domain)
67	     */
68	    public boolean isDisposable(String email) {
69	        String domain = domainOf(email);
70	        return domain != null && DISPOSABLE_EMAIL_DOMAINS.contains(domain);
71	    }
72	
73	    /**
74	     * Whether an email's {@link #domainOf domain} is <em>disposable-adjacent</em>: it shares its
75	     * registrable domain label (the label immediately before the final top-level domain) with a
76	     * known disposable domain, without necessarily being one of them. This catches the near
77	     * neighbours of the disposable domains — the same provider under a different top-level domain
78	     * (e.g. {@code mailinator.net}) or a subdomain of one (e.g. {@code inbox.mailinator.com}) —
79	     * which the exact-match {@link #isDisposable disposable} check does not reject on create.
80	     *
81	     * @param email an email address, expected to carry a single '@'
82	     * @return {@code true} if the email's domain shares a registrable label with a known disposable
83	     *         domain, {@code false} otherwise (including when the email has no domain)
84	     */
85	    public boolean isDisposableAdjacent(String email) {
86	        String label = registrableLabel(domainOf(email));
87	        if (label == null) {
88	            return false;
89	        }
90	        return DISPOSABLE_EMAIL_DOMAINS.stream()
91	            .map(EmailDomainClassifier::registrableLabel)
92	            .anyMatch(label::equals);
93	    }
94	
95	    /**
96	     * The registrable label of a domain: the dot-delimited component immediately before its final
97	     * top-level domain (e.g. 'mailinator' for both 'mailinator.com' and 'inbox.mailinator.co.uk').
98	     * Returns {@code null} when {@code domain} is {@code null} or has no such component.
99	     */
100	    private static String registrableLabel(String domain) {
101	        if (domain == null) {
102	            return null;
103	        }
104	        String[] parts = domain.split("\\.");
105	        return parts.length < 2 ? null : parts[parts.length - 2];
106	    }
107	}
