17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
32	import org.springframework.security.access.AccessDeniedException;
33	import org.springframework.validation.BindingResult;
34	import org.springframework.validation.FieldError;
35	import org.springframework.web.bind.MethodArgumentNotValidException;
36	import org.springframework.web.bind.annotation.ControllerAdvice;
37	import org.springframework.web.bind.annotation.ExceptionHandler;
38	import org.springframework.web.bind.annotation.ResponseBody;
39	
40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	
56	    /**
57	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
58	     * class.
59	     *
60	     * @param e     Object referring to the thrown exception.
61	     * @param status HTTP response status.
62	     * @param url URL request.
63	     */
64	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
65	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
66	        problemDetail.setType(URI.create(url.toString()));
67	        problemDetail.setTitle(e.getClass().getSimpleName());
68	        problemDetail.setDetail(detail);
69	        problemDetail.setProperty("timestamp", Instant.now());
70	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
71	        return problemDetail;
72	    }
73	
74	    /**
75	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
76	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
77	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
78	     * would catch it and report an authorization failure as a 500.
79	     *
80	     * @param e The {@link AccessDeniedException} to propagate
81	     * @throws AccessDeniedException always
82	     */
83	    @ExceptionHandler(AccessDeniedException.class)
84	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
85	        throw e;
86	    }
87	
88	    /**
89	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
90	     *
91	     * @param e The {@link Exception} to be handled
92	     * @param request {@link HttpServletRequest} object referring to the current request.
93	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
94	     */
95	    @ExceptionHandler(Exception.class)
96	    @ResponseBody
97	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
98	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
99	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
100	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
101	        return ResponseEntity.status(status).body(detail);
102	    }
103	
104	    /**
105	     * Handles a {@link OwnerRegistrationException} raised when a create rule refuses to register an
106	     * owner, reporting the HTTP status the rejected rule maps to ({@code 400}, {@code 409} or
107	     * {@code 429}). This is the single place the owner-create rejections are turned into a response.
108	     *
109	     * @param e The {@link OwnerRegistrationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} carrying the rejection's HTTP status
112	     */
113	    @ExceptionHandler(OwnerRegistrationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleOwnerRegistrationException(OwnerRegistrationException e, HttpServletRequest request) {
116	        logger.warn("Owner registration rejected at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getReason());
120	        HttpStatus status = e.getStatus();
121	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getReason().getDetail());
122	        return ResponseEntity.status(status).body(detail);
123	    }
124	
125	    /**
126	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
127	     * method returns a 404 Not Found status if an entity does not exist.
128	     *
129	     * @param e The {@link DataIntegrityViolationException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
132	     */
133	    @ExceptionHandler(DataIntegrityViolationException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
136	        logger.warn("Data integrity violation at {} {}: {}",
137	            request.getMethod(),
138	            request.getRequestURI(),
139	            e.getMessage());
140	        logger.debug("Data integrity violation stacktrace", e);
141	        HttpStatus status = HttpStatus.NOT_FOUND;
142	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
143	        return ResponseEntity.status(status).body(detail);
144	    }
145	
146	    /**
147	     * Handles exception thrown by Bean Validation on controller methods parameters
148	     *
149	     * @param e The {@link MethodArgumentNotValidException} to be handled
150	     * @param request {@link HttpServletRequest} object referring to the current request.
151	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
152	     */
153	    @ExceptionHandler(MethodArgumentNotValidException.class)
154	    @ResponseBody
155	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
156	        HttpStatus status = HttpStatus.BAD_REQUEST;
157	        BindingResult bindingResult = e.getBindingResult();
158	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
159	        if (bindingResult.hasErrors()) {
160	            List<FieldError> fieldErrors = bindingResult.getFieldErrors();
161	            logger.debug("Validation error at {} {}: {}",
162	                request.getMethod(),
163	                request.getRequestURI(),
164	                fieldErrors);
165	            detail.setProperty("schemaValidationErrors", toSchemaValidationErrors(fieldErrors));
166	            detail.setProperty("errors", toRejectedFieldNames(fieldErrors));
167	        }
168	        return ResponseEntity.status(status).body(detail);
169	    }
170	
171	    /**
172	     * Maps each rejected field to a {@link ValidationMessageDto} describing why it was rejected.
173	     *
174	     * @param fieldErrors the field-level errors collected by Bean Validation
175	     * @return one validation message per field error, in order
176	     */
177	    /**
178	     * Collects the distinct names of the fields rejected by Bean Validation, preserving the order in
179	     * which they were reported. Used to expose a simple {@code errors} array (one entry per offending
180	     * field, e.g. a required field that is missing or blank) alongside the detailed messages.
181	     *
182	     * @param fieldErrors the field-level errors collected by Bean Validation
183	     * @return the rejected field names, without duplicates
184	     */
185	    private List<String> toRejectedFieldNames(List<FieldError> fieldErrors) {
186	        return fieldErrors.stream()
187	            .map(FieldError::getField)
188	            .distinct()
189	            .toList();
190	    }
191	
192	    private List<ValidationMessageDto> toSchemaValidationErrors(List<FieldError> fieldErrors) {
193	        return fieldErrors.stream()
194	            .map(this::toValidationMessage)
195	            .toList();
196	    }
197	
198	    private ValidationMessageDto toValidationMessage(FieldError fieldError) {
199	        String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
200	        String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
201	        String message = "Field '%s' %s (rejected value: %s)".formatted(
202	            fieldError.getField(),
203	            defaultMessage,
204	            rejectedValue);
205	        return new ValidationMessageDto(message)
206	            .putAdditionalProperty("field", fieldError.getField())
207	            .putAdditionalProperty("rejectedValue", rejectedValue)
208	            .putAdditionalProperty("defaultMessage", defaultMessage);
209	    }
210	
211	}
