17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Locale;
20	
21	/**
22	 * Small stateless helpers for the string normalisation that backs the application's
23	 * identity comparisons.
24	 *
25	 * <p>Keeping the normalisation in one place means every identity comparison keys on the
26	 * same canonical form and they can never drift apart.
27	 */
28	public abstract class IdentityUtils {
29	
30	    /**
31	     * Normalize a value for identity comparison: null becomes an empty string, surrounding
32	     * whitespace is trimmed, internal whitespace runs collapse to a single space, and the
33	     * result is lower-cased.
34	     *
35	     * @param value the raw value to normalize, possibly {@code null}
36	     * @return the canonical, lower-cased form, or the empty string if {@code value} is {@code null}
37	     */
38	    public static String normalizeIdentity(String value) {
39	        if (value == null) {
40	            return "";
41	        }
42	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
43	    }
44	
45	    /**
46	     * The American Soundex code of {@code value}: its first letter followed by three digits that
47	     * encode the remaining consonants, so names that sound alike collapse to the same code (e.g.
48	     * 'Robert' and 'Rupert' both yield 'R163'). Letters are folded to their {@link #soundexDigit
49	     * digit class}; vowels (and 'y') separate equal-class letters while 'h' and 'w' do not, runs of
50	     * an equal class code once, and the result is padded with zeros or truncated to four characters.
51	     *
52	     * @param value the raw value to encode, possibly {@code null}
53	     * @return the four-character Soundex code, or the empty string when {@code value} is {@code null}
54	     *         or holds no letters
55	     */
56	    public static String soundex(String value) {
57	        if (value == null) {
58	            return "";
59	        }
60	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
61	        if (letters.isEmpty()) {
62	            return "";
63	        }
64	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
65	        int previous = soundexDigit(letters.charAt(0));
66	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
67	            char c = letters.charAt(i);
68	            // 'h' and 'w' are transparent: they neither code nor break a run of an equal digit class.
69	            if (c == 'H' || c == 'W') {
70	                continue;
71	            }
72	            int digit = soundexDigit(c);
73	            if (digit != 0 && digit != previous) {
74	                code.append((char) ('0' + digit));
75	            }
76	            // A vowel (digit 0) resets the run, so an equal class either side of it codes twice.
77	            previous = digit;
78	        }
79	        while (code.length() < 4) {
80	            code.append('0');
81	        }
82	        return code.toString();
83	    }
84	
85	    /**
86	     * The Soundex digit class (1-6) of an upper-case letter, or 0 for a vowel, 'h', 'w', 'y' or any
87	     * character that Soundex does not code: b/f/p/v -> 1, c/g/j/k/q/s/x/z -> 2, d/t -> 3, l -> 4,
88	     * m/n -> 5, r -> 6.
89	     *
90	     * @param letter the upper-case letter to classify
91	     * @return the letter's Soundex digit class, or 0 when it is not coded
92	     */
93	    private static int soundexDigit(char letter) {
94	        return switch (letter) {
95	            case 'B', 'F', 'P', 'V' -> 1;
96	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> 2;
97	            case 'D', 'T' -> 3;
98	            case 'L' -> 4;
99	            case 'M', 'N' -> 5;
100	            case 'R' -> 6;
101	            default -> 0;
102	        };
103	    }
104	}
